        for _, kid in ipairs(n.body) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'Assign' then
        kids[#kids + 1] = n.value
    elseif n.tag == 'Assume' then
        kids[#kids + 1] = n.cond
    elseif n.tag == 'Check' then
        kids[#kids + 1] = n.cond
    elseif n.tag == 'Branch' then
        kids[#kids + 1] = n.cond
        for _, kid in ipairs(n.then_body) do
            kids[#kids + 1] = kid
        end
        for _, kid in ipairs(n.else_body) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'Choice' then
        for _, kid in ipairs(n.first) do
            kids[#kids + 1] = kid
        end
        for _, kid in ipairs(n.second) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'Block' then
        for _, kid in ipairs(n.body) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'BinOp' then
        kids[#kids + 1] = n.lhs
        kids[#kids + 1] = n.rhs
    elseif n.tag == 'Not' then
        kids[#kids + 1] = n.arg
